CREATE OR REPLACE FUNCTION public.check_project_permission(p_project_id uuid, p_user_id uuid, p_required_role text DEFAULT 'viewer'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    user_role TEXT;
    is_owner BOOLEAN;
BEGIN
    -- オーナーかチェック
    SELECT EXISTS(
        SELECT 1 FROM public.projects 
        WHERE id = p_project_id AND owner_id = p_user_id
    ) INTO is_owner;

    IF is_owner THEN
        RETURN TRUE;
    END IF;

    -- メンバーロールをチェック
    SELECT role INTO user_role
    FROM public.project_members
    WHERE project_id = p_project_id AND user_id = p_user_id;

    IF user_role IS NULL THEN
        RETURN FALSE;
    END IF;

    -- 権限レベルをチェック
    CASE p_required_role
        WHEN 'viewer' THEN RETURN user_role IN ('viewer', 'editor', 'admin');
        WHEN 'editor' THEN RETURN user_role IN ('editor', 'admin');
        WHEN 'admin' THEN RETURN user_role = 'admin';
        ELSE RETURN FALSE;
    END CASE;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_test_data()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    -- 注意: この関数は開発環境でのみ使用してください
    RAISE NOTICE 'Cleaning up test data...';

    DELETE FROM public.activity_logs;
    DELETE FROM public.reference_tags;
    DELETE FROM public.selected_texts;
    DELETE FROM public.bookmarks;
    DELETE FROM public.references;
    DELETE FROM public.project_members;
    DELETE FROM public.projects;
    DELETE FROM public.citation_settings;
    -- プロファイルとタグは保持

    RAISE NOTICE 'Test data cleanup completed.';
END;
$function$

CREATE OR REPLACE FUNCTION public.create_development_test_data()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    test_user_id UUID;
    test_project_id UUID;
BEGIN
    -- この関数は開発環境でのみ実行すること
    -- 本番環境では絶対に実行しないでください

    RAISE NOTICE 'Creating development test data...';

    -- テストユーザーのプロファイルが存在する場合のみ実行
    SELECT id INTO test_user_id FROM public.profiles LIMIT 1;

    IF test_user_id IS NOT NULL THEN
        -- デフォルト引用設定を作成
        PERFORM create_default_citation_settings(test_user_id);

        -- IBプロジェクトテンプレートを作成
        PERFORM create_ib_project_templates(test_user_id);

        -- 最初のプロジェクトにチュートリアル参照を追加
        SELECT id INTO test_project_id FROM public.projects WHERE owner_id = test_user_id LIMIT 1;

        IF test_project_id IS NOT NULL THEN
            PERFORM create_tutorial_references(test_user_id, test_project_id);
        END IF;

        RAISE NOTICE 'Development test data created successfully for user: %', test_user_id;
    ELSE
        RAISE NOTICE 'No user profiles found. Test data not created.';
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = timezone('utc'::text, now());
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.regenerate_link_sharing_token(p_project_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  new_token uuid;
BEGIN
  -- オーナーのみが実行可能
  IF NOT EXISTS (
    SELECT 1 FROM public.projects 
    WHERE id = p_project_id AND owner_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Only project owner can regenerate sharing token';
  END IF;

  new_token := uuid_generate_v4();

  UPDATE public.projects 
  SET link_sharing_token = new_token, 
      updated_at = timezone('utc'::text, now())
  WHERE id = p_project_id;

  RETURN new_token;
END;
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_project_references()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
    UPDATE "references" 
    SET deleted_at = NEW.deleted_at, deleted_by = NEW.deleted_by
    WHERE project_id = NEW.id AND deleted_at IS NULL;
  END IF;

  IF NEW.deleted_at IS NULL AND OLD.deleted_at IS NOT NULL THEN
    UPDATE "references" 
    SET deleted_at = NULL, deleted_by = NULL
    WHERE project_id = NEW.id AND deleted_by = OLD.deleted_by;
  END IF;

  RETURN NEW;
END;
$function$
